// Two-phase upload from the bundle
const file = fileInput.files[0];
const path = `images/${crypto.randomUUID()}.png`;
const init = await anna.files.upload_init({
  path,
  content_type: file.type,
  size: file.size,
  ttl_seconds: 600,
  metadata: { source: 'paste' },
  tags: ['user-upload']
});
// Browser streams bytes straight to R2 — server never sees them
const put = await fetch(init.put_url, {
  method: 'PUT',
  headers: init.headers,
  body: file
});
if (!put.ok) throw new Error(`R2 PUT ${put.status}`);
const etag = put.headers.get('etag');
// Reuse the SAME path from upload_init — finalize matches the pending row by (user, app, path).
const entry = await anna.files.upload_finalize({ path, etag, size: file.size });
console.log('stored', entry.path, entry.etag);

// continued from upload_init example
const entry = await anna.files.upload_finalize({
  path: 'images/abc.png',
  etag,            // from the R2 PUT response
  size: file.size
});
// `entry.etag` is now stable — store it for future if_match writes
await anna.storage.set({ key: 'last_upload', value: { path: entry.path, etag: entry.etag } });

const u = await anna.files.download_url({ path: 'images/abc.png', ttl_seconds: 900 });
img.src = u.get_url;
// Force a download instead of inline render:
const dl = await anna.files.download_url({
  path: 'reports/q3.pdf',
  disposition: 'attachment; filename="q3.pdf"'
});
location.href = dl.get_url;

// Manifest: ui.host_api.files must include "download".
const r = await anna.files.download({
  path: 'exports/q3-deck.pptx',
  filename: 'Q3 業績報告.pptx'
});
// r = { ok: true, filename: 'Q3 業績報告.pptx', size_bytes: …, … }
// The browser save dialog was opened by the HOST page; r.get_url does not exist.

let cursor = null;
const all = [];
do {
  const page = await anna.files.list({ prefix: 'images/', cursor, limit: 200 });
  all.push(...page.items);
  cursor = page.next_cursor;
} while (cursor);
console.log(`${all.length} images`);

// Safe delete: refuse if someone re-uploaded since we last looked
const page = await anna.files.list({ prefix: 'images/', limit: 1 });
const { path, etag } = page.items[0];
try {
  await anna.files.delete({ path, if_match: etag });
} catch (e) {
  if (e.code === 'precondition_failed') {
    // someone else rewrote it; reload and re-confirm with the user
  } else {
    throw e;
  }
}
